installScripts.windows:
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$env:PYTHONUTF8 = '1'
$env:PYTHONIOENCODING = 'utf-8'
[Console]::OutputEncoding = New-Object Text.UTF8Encoding($false)
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

# GSCS sets the current directory to the instance root.
$work = Join-Path (Get-Location).Path '.gscs-minecraft'
$pythonRoot = Join-Path $work 'python'
$python = Join-Path $pythonRoot 'python.exe'
$pythonVersion = '3.14.10'
$architecture = $env:PROCESSOR_ARCHITEW6432
if ([string]::IsNullOrWhiteSpace($architecture)) { $architecture = $env:PROCESSOR_ARCHITECTURE }
switch ($architecture.ToUpperInvariant()) {
    'AMD64' {
        $archiveUrl = 'https://www.python.org/ftp/python/3.14.10/python-3.14.10-embeddable-amd64.zip'
        $archiveSha256 = 'b553e7dac884469b40e0740bb527271c3378f700b427e0485835f1bb6424361c'
    }
    'ARM64' {
        $archiveUrl = 'https://www.python.org/ftp/python/3.14.10/python-3.14.10-embeddable-arm64.zip'
        $archiveSha256 = '5faf08027ec9d0ae7c346465464aa66bbc2f3b54a37d696c54024825ea29d02d'
    }
    default { throw 'Diese Vorlage benötigt Windows x64 oder Windows ARM64.' }
}
$stamp = Join-Path $pythonRoot '.gscs-version'
$expectedStamp = $pythonVersion + '-' + $architecture.ToLowerInvariant()
$needsPython = !(Test-Path -LiteralPath $python)
if (!(Test-Path -LiteralPath $stamp)) { $needsPython = $true }
elseif ((Get-Content -LiteralPath $stamp -Raw).Trim() -ne $expectedStamp) { $needsPython = $true }

if ($needsPython) {
    Write-Output ('[GSCS Minecraft] Installiere portable Python-Laufzeit ' + $pythonVersion + '.')
    $staging = Join-Path $work ('python-stage-' + [Guid]::NewGuid().ToString('N'))
    $zipPath = $staging + '.zip'
    $oldPython = Join-Path $work ('python-previous-' + [Guid]::NewGuid().ToString('N'))
    try {
        Invoke-WebRequest -UseBasicParsing -Uri $archiveUrl -OutFile $zipPath -UserAgent 'GSCS-Minecraft/1.0 (https://github.com/ZUMBYTE-AppSolution/gscs-deployment)'
        $actualHash = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($actualHash -ne $archiveSha256) { throw 'Prüfsumme der Python-Laufzeit stimmt nicht überein.' }
        Expand-Archive -LiteralPath $zipPath -DestinationPath $staging -Force
        if (!(Test-Path -LiteralPath (Join-Path $staging 'python.exe'))) { throw 'Python-Archiv enthält keine ausführbare Laufzeit.' }
        & (Join-Path $staging 'python.exe') -c 'import ssl, zipfile, tarfile, hashlib'
        if ($LASTEXITCODE -ne 0) { throw 'Die portable Python-Laufzeit lässt sich nicht ausführen.' }
        [IO.File]::WriteAllText((Join-Path $staging '.gscs-version'), $expectedStamp, (New-Object Text.UTF8Encoding($false)))
        if (Test-Path -LiteralPath $pythonRoot) { Move-Item -LiteralPath $pythonRoot -Destination $oldPython }
        try { Move-Item -LiteralPath $staging -Destination $pythonRoot }
        catch {
            if (Test-Path -LiteralPath $oldPython) { Move-Item -LiteralPath $oldPython -Destination $pythonRoot }
            throw
        }
        if (Test-Path -LiteralPath $oldPython) { Remove-Item -LiteralPath $oldPython -Recurse -Force }
    }
    finally {
        if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
        if (Test-Path -LiteralPath $staging) { Remove-Item -LiteralPath $staging -Recurse -Force }
    }
}

$package = Get-Content -LiteralPath (Join-Path $work 'sources.json') -Raw -Encoding UTF8 | ConvertFrom-Json
foreach ($item in $package.files) {
    if ($item.name -notin @('minecraft_installer.py', 'minecraft_configure.py', 'config-fields.json')) {
        throw 'Unbekannte Datei im eingebetteten Vorlagenpaket.'
    }
    $bytes = [Convert]::FromBase64String($item.base64)
    $hasher = [Security.Cryptography.SHA256]::Create()
    try { $hash = [BitConverter]::ToString($hasher.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant() }
    finally { $hasher.Dispose() }
    if ($hash -ne $item.sha256) { throw ('Prüfsummenfehler im eingebetteten Vorlagenpaket: ' + $item.name) }
    $target = Join-Path $work $item.name
    [IO.File]::WriteAllBytes(($target + '.new'), $bytes)
    Move-Item -LiteralPath ($target + '.new') -Destination $target -Force
}
& $python (Join-Path $work 'minecraft_installer.py') install
if ($LASTEXITCODE -ne 0) { throw 'Minecraft-Installation ist fehlgeschlagen. Details stehen im vorherigen Protokoll.' }
& $python (Join-Path $work 'minecraft_configure.py')
if ($LASTEXITCODE -ne 0) { throw 'Minecraft-Konfiguration ist ungültig. Details stehen im vorherigen Protokoll.' }
